import React, { useState } from "react";
import "./UploadPage.css"; // Import CSS

const UploadPage = () => {
  const [file, setFile] = useState(null);
  const [progress, setProgress] = useState(100); // Simulating 100% uploaded file

  const handleFileUpload = (event) => {
    const uploadedFile = event.target.files[0];
    if (uploadedFile) {
      setFile(uploadedFile);
      setProgress(100);
    }
  };

  return (
    <div className="upload-container">
      <h2>Please Upload your Swagger Document</h2>
      <p>Upload your Swagger YAML file (optional) and/or enter a custom prompt</p>

      <div className="upload-box">
        <label className="file-upload-label">
          <input type="file" onChange={handleFileUpload} className="file-input" />
          <div className="upload-content">
            <img src="folder-icon.png" alt="Upload" className="folder-icon" />
            <p>Select a file or drag and drop here</p>
            <span>Upload swagger docs size no more than 200 MB</span>
          </div>
        </label>
        <button className="browse-btn">Browse files</button>
      </div>

      {file && (
        <div className="file-info">
          <span className="file-icon">📄</span>
          <span className="file-name">{file.name}</span>
          <span className="file-size">{(file.size / 1024).toFixed(1)} KB</span>
        </div>
      )}

      {file && (
        <div className="progress-container">
          <div className="progress-bar" style={{ width: `${progress}%` }}></div>
          <span className="progress-text">{progress}%</span>
        </div>
      )}
    </div>
  );
};

export default UploadPage;
